class TokenBucket:
    def __init__(self, cap, rate):
        self.cap, self.rate = float(cap), float(rate)
        self.tokens, self.last = float(cap), 0.0
        self.ok = self.no = 0

    def allow(self, now_ms):
        dt = max(0.0, (now_ms - self.last) / 1000.0)
        self.tokens = min(self.cap, self.tokens + dt * self.rate)
        self.last = now_ms
        if self.tokens >= 1.0:
            self.tokens -= 1.0; self.ok += 1; return True
        self.no += 1; return False

for cap in (10, 1):
    b = TokenBucket(cap, 5)
    seq = [0.0] * 12 + [s * 1000.0 for s in range(1, 5) for _ in range(3)]
    for t in seq:
        b.allow(t)
    print(f"C={cap}: 放行 {b.ok}, 拒绝 {b.no}, 利用率 {b.ok/(cap+20):.1%}")
